dataTableFormat:
{
  "is multi section": "true",
  "search parameters": [
    {
      "parameter": "phenotype",
      "label": "Phenotype",
      "type": "list",
      "values": "kp phenotypes"
    },
    {
      "parameter": "ancestry",
      "label": "Ancestry",
      "type": "list",
      "values": [
        {
          "label": "African American",
          "value": "AA"
        },
        {
          "label": "East Asian",
          "value": "EA"
        },
        {
          "label": "Hispanic",
          "value": "HS"
        },
        {
          "label": "South Asian",
          "value": "SA"
        },
        {
          "label": "Europian",
          "value": "EU"
        }
      ]
    }
  ],
  "sections": [
    {
      "section id": "globalEnrichment",
      "header": "Global Enrichment",
      "data point": {
        "type": "bioindex",
        "url": "https://bioindex.hugeamp.org/api/bio/",
        "index": "global-enrichment",
        "parameters": [
          "phenotype"
        ],
        "parameters type": "array",
        "data type": "bioindex",
        "cumulate data": "true"
      },
      "table format": {
        "data convert": [
          {
            "type": "join multi",
            "field name": "Tissue Annotation",
            "fields to join": [
              "tissue",
              "annotation"
            ],
            "join by": [
              "_"
            ]
          },
          {
            "type": "join multi",
            "field name": "PheAnceAnnoTiss",
            "fields to join": [
              "phenotype",
              "ancestry",
              "annotation",
              "tissue"
            ],
            "join by": [
              "_",
              "_",
              "_"
            ]
          },
          {
            "type": "join multi",
            "field name": "Phenotype Ancestry",
            "fields to join": [
              "phenotype",
              "ancestry"
            ],
            "join by": [
              "_"
            ]
          },
          {
            "type": "raw",
            "field name": "Phenotype",
            "raw field": "phenotype"
          },
          {
            "type": "raw",
            "field name": "Ancestry",
            "raw field": "ancestry"
          },
          {
            "type": "raw",
            "field name": "Annotation",
            "raw field": "annotation"
          },
          {
            "type": "raw",
            "field name": "Set Annotation",
            "raw field": "annotation"
          },
          {
            "type": "raw",
            "field name": "Set Tissue",
            "raw field": "tissue"
          },
          {
            "type": "raw",
            "field name": "Tissue",
            "raw field": "tissue"
          },
          {
            "type": "raw",
            "field name": "Expected SNPs",
            "raw field": "expectedSNPs"
          },
          {
            "type": "raw",
            "field name": "SNPs",
            "raw field": "SNPs"
          },
          {
            "type": "raw",
            "field name": "P-Value",
            "raw field": "pValue"
          },
          {
            "type": "calculate",
            "field name": "P-Value(-log10)",
            "raw field": "pValue",
            "calculation type": "-log10"
          },
          {
            "type": "calculate",
            "field name": "Fold",
            "expression": [
              "SNPs",
              "/",
              "expectedSNPs"
            ],
            "calculation type": "math"
          },
          {
            "type": "calculate",
            "field name": "Test",
            "expression": [
              "(",
              "SNPs",
              "/",
              "expectedSNPs",
              ")",
              "*",
              "pValue"
            ],
            "calculation type": "math"
          }
        ],
        "top rows": [
          "Tissue",
          "Annotation",
          "Phenotype Ancestry",
          "P-Value",
          "Expected SNPs",
          "SNPs",
          "Fold",
          "Set Annotation",
          "Set Tissue"
        ],
        "column formatting": {
          "P-Value": {
            "type": [
              "scientific notation"
            ]
          },
          "Expected SNPs": {
            "type": [
              "scientific notation"
            ]
          },
          "SNPs": {
            "type": [
              "scientific notation"
            ]
          },
          "Fold": {
            "type": [
              "scientific notation"
            ]
          },
          "Set Annotation": {
            "type": [
              "set parameter"
            ],
            "parameter": "annotation",
            "target sections": [
              "tissueRegions"
            ]
          },
          "Set Tissue": {
            "type": [
              "set parameter"
            ],
            "parameter": "tissue",
            "target sections": [
              "tissueRegions"
            ]
          }
        },
        "group by": [
          "Phenotype Ancestry"
        ],
        "compare data": {
          "key field": "Tissue Annotation",
          "fields to compare": [
            "Phenotype Ancestry",
            "P-Value",
            "Expected SNPs",
            "SNPs",
            "Fold"
          ]
        }
      },
      "visualizer": {
        "type": "scatter plot",
        "render type": "single plot",
        "group by": "Phenotype Ancestry",
        "color by": "Annotation",
        "y axis field": "Fold",
        "y axis label": "Fold (SNPs/expectedSNPs)",
        "x axis field": "P-Value(-log10)",
        "x axis label": "-Log10(p-value)",
        "ticks decimal point": "2",
        "render by": "PheAnceAnnoTiss",
        "hover content": [
          "P-Value",
          "Expected SNPs",
          "SNPs",
          "Fold"
        ],
        "height": 120,
        "width": 200,
        "plot margin": {
          "left": 60,
          "right": 20,
          "top": 40,
          "bottom": 50,
          "bump": 5
        }
      },
      "filters": [
        {
          "field": "Ancestry",
          "label": "Ancestry",
          "type": "checkbox"
        },
        {
          "field": "Annotation",
          "label": "Annotation",
          "type": "checkbox"
        },
        {
          "field": "Tissue",
          "label": "Tissue",
          "type": "checkbox"
        }
      ]
    }
  ]
}
